WITH latest AS (SELECT * FROM accounts QUALIFY ROW_NUMBER() OVER (PARTITION BY status, account_type ORDER BY opened_date DESC NULLS FIRST, id) = 1) SELECT CASE WHEN balance >= 75000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, DATE_TRUNC('YEAR', opened_date) AS year_start, COUNT(CASE WHEN status = 'CLOSED' THEN 1 END) AS closed_count, ROUND(AVG(balance), 2) AS avg_balance, PERCENTILE_APPROX(balance, 0.95) AS balance_p95, PERCENT_RANK() OVER (PARTITION BY CASE WHEN balance >= 75000 THEN 'HIGH' ELSE 'LOW' END ORDER BY PERCENTILE_APPROX(balance, 0.95) DESC) AS balance_p95_percent_rank FROM latest GROUP BY 1, 2 HAVING COUNT(CASE WHEN status = 'CLOSED' THEN 1 END) > 1 ORDER BY balance_p95 DESC NULLS FIRST
